head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF20508.xml";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vJobMode = "";
scwin.vBZ_PROCS_NO = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/*
 * init()
 */
scwin.fn_init = function() {
    edt_SDate.setValue("20110101");
    edt_EDate.setValue(scwin.vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    var depCds = "";
    if (scwin.gLdMktTp == '1') depCds = '2520,2615'; //2520 상장심사팀,  2615 기업심사팀


    else if (scwin.gLdMktTp == '2') depCds = '3510,3H10,3H20'; //3510 기업심사1팀, 3H10 기업심사2팀, 3H20기업심사3팀


    else depCds = '2520,2615,3510,3H10,3H20';
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=CODE_EMPDEP_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.listingcommonbiz.select.dep.condition2" + "&{P}param01=" + depCds;
    dts_DEP_CD.DataID = encodeURI(url);
    dts_DEP_CD.reset();
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=CODE_EMPDEP_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.listingcommonbiz.select.emp.condition2" + "&{P}param01=" + depCds;
    dts_EMP_NO.DataID = encodeURI(url);
    dts_EMP_NO.reset();
    var arrCid = [{
        cid: "REAL_INVSTG_STEP_CD",
        cnm: "cmb_REAL_INVSTG_STEP_CD"
    }, {
        cid: "REAL_INVSTG_MAJ_CONTN_CD",
        cnm: "cmb_REAL_INVSTG_MAJ_CONTN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='REAL_INVSTG_STEP_CD','REAL_INVSTG_MAJ_CONTN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    var strGubun = "";
    for (var i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        if (arrCid[i].cid == 'REAL_INVSTG_STEP_CD' || arrCid[i].cid == 'REAL_INVSTG_MAJ_CONTN_CD') {
            strCbd = "^' '";
        }
        for (var j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strGubun = dts_Cod.getCellData(j, "VALUE").substring(0, 1); //코 1XX, 유 2XX
                if (scwin.gLdMktTp == strGubun) {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                } else if (scwin.gLdMktTp == '9') {
                    strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_list_sync = function() {
    var ldMktTp = scwin.gLdMktTp;
    if (scwin.gLdMktTp == "9") ldMktTp = "";
    var url = "/RealInvstg.do?SCREN_ID=ULDSTF20506.gfm&SCREN_PROCES_TP_CD=01&method=getRealInvstgDataList" + "&outputMessageId=REAL_INVSTG_DATA" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&S_REG_DD=" + $c.stf.getObjectValue(edt_SDate) + "&E_REG_DD=" + $c.stf.getObjectValue(edt_EDate) + "&REAL_INVSTG_STEP_CD=" + $c.stf.getObjectValue(cmb_REAL_INVSTG_STEP_CD) + "&REAL_INVSTG_MAJ_CONTN_CD=" + $c.stf.getObjectValue(cmb_REAL_INVSTG_MAJ_CONTN_CD) + "&FILE_CONTENT=" + $c.stf.getObjectValue(txb_FileContents) + "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO) + "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD) + "&MKT_TP_CD=" + ldMktTp;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "실질심사자료 조회", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_GetParIsur = function(arrPar) {
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
    }
};
scwin.fn_setPara = function(obj) {
    if (scwin.vJobMode == "M") {
        scwin.vBZ_PROCS_NO = dts_List.getCellData(obj, "BZ_PROCS_NO");
    } else {
        scwin.vBZ_PROCS_NO = "";
    }
};
scwin.fn_getBZ_PROCS_NO = function() {
    return scwin.vBZ_PROCS_NO;
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Input_onclick = async function() {
    scwin.vJobMode = "I";
    scwin.fn_setPara(0);
    var wth = 700;
    var hgt = 500;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("gform", "/lstsrch/ULDSTF20509.gfm", "실질심사 자료입력", pt.x, pt.y, wth, hgt, "window");
    scwin.vJobMode = "";
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_list_sync();
    }
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_COM_NM_onkeydown = function() {
    if (window.event.keyCode == 13) {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            scwin.fn_list_sync();
        }
    }
};
scwin.txb_FileContents_onkeydown = function() {
    if (window.event.keyCode == 13) {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            scwin.fn_list_sync();
        }
    }
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    scwin.vJobMode = "M";
    scwin.fn_setPara(row);
    var wth = 700;
    var hgt = 500;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("gform", "/lstsrch/ULDSTF20509.gfm", "실질심사 자료입력", pt.x, pt.y, wth, hgt, "window");
    scwin.vJobMode = "";
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_init();
    scwin.fn_list_sync();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    Grd_com_isur.style.zIndex = 30;
};
